private void updateVisualEffects(float delta) {
    // Update all visuals and remove inactive ones
    for (int i = activeVisuals.size() - 1; i >= 0; i--) {
        AbilityVisual visual = activeVisuals.get(i);
        visual.update(delta);
        if (!visual.isActive()) {
            visual.dispose();
            activeVisuals.remove(i);
        }
    }
}
